CustomField.formula:
IF ( OR (
/*Adhoc*/ AND ( ISPICKVAL ( Type , "Adhoc"), OR ( ISPICKVAL ( Sub_Type__c , "Platinum Accelerate"), ISPICKVAL ( Sub_Type__c , "Gold Accelerate"), ISPICKVAL ( Sub_Type__c , "50% Bonus Status Credits"), ISPICKVAL ( Sub_Type__c , "Gold Accelerate + 90 Days QC"), ISPICKVAL ( Sub_Type__c , "Platinum Accelerate + 90 Days QC") ), Presence_of_Frequent_Flyer_Information__c >= 1 ),
/*Adhoc*/ AND ( ISPICKVAL ( Type , "Adhoc"), OR ( ISPICKVAL ( Sub_Type__c , "FOC Qantas Club Waiver"), ISPICKVAL ( Sub_Type__c , "QC Member Gifting"), ISPICKVAL ( Sub_Type__c , "90 Days QC FOC") ) ),
/*Campaign*/ AND ( ISPICKVAL ( Type , "Campaign"), OR ( ISPICKVAL ( Sub_Type__c , "Platinum Accelerate"), ISPICKVAL ( Sub_Type__c , "Gold Accelerate"), ISPICKVAL ( Sub_Type__c , "50% Bonus Status Credits"), ISPICKVAL ( Sub_Type__c , "FOC Qantas Club Waiver"), ISPICKVAL ( Sub_Type__c , "Corporate Trigger - 50% Bonus Status") ) ),
AND( NOT ( ISPICKVAL ( Type ," ")), NOT( ISPICKVAL ( Sub_Type__c , "Platinum Accelerate")), NOT ( ISPICKVAL ( Sub_Type__c , "Gold Accelerate")), NOT (ISPICKVAL ( Sub_Type__c , "50% Bonus Status Credits")), NOT(ISPICKVAL ( Sub_Type__c , "QC Member Gifting")) ) )
,TRUE, FALSE )
